custom_css:
/* ============================================================
 * Nord-Dark — SillyTavern 主题 v3
 * 设计语言按官方文档（nordtheme.com/docs/colors-and-palettes）+ 官网设计系统：
 * - Polar Night 明度分层：nord0 画布 / nord1 浮起（面板）/ nord2 亮阶·组件底·选中 / nord3 导向标记·发丝线
 * - Snow Storm 文字阶：nord4 正文 / nord5 hover 增亮 / nord6 需更多注意的文字
 * - Frost 强调级：nord8 主强调（primary action/focus） / nord9 次级 / nord10 三级
 * - Aurora 语义态：nord11 错误 / nord13 警告 / nord14 成功（nord15 仅数字字面量）
 * - 官方 passive border = nord1/nord2 发丝线（本主题加回，给结构与设计感）
 * - 官方选区/高亮 = nord2 底 + nord6 字
 * 字体：Rubik（UI）+ HarmonyOS Sans SC（中文回落，可读性）+ Source Code Pro（等宽）
 * 动效：easeOutCubic；圆角 3px（冰/棱角气质）
 * ============================================================ */

/* ---字体加载--- */
@import url('https://cdn.jsdelivr.net/npm/@fontsource/rubik@5.0.0/index.css');
@import url('https://cdn.jsdelivr.net/npm/@fontsource/rubik@5.0.0/500.css');
@import url('https://cdn.jsdelivr.net/npm/@fontsource/rubik@5.0.0/600.css');
@import url('https://cdn.jsdelivr.net/npm/@fontsource/source-code-pro@5.0.0/index.css');
@import url('https://cdn.jsdelivr.net/npm/@lobehub/webfont-harmony-sans-sc@1.0.0/css/index-full.css');

/* ---Nord 原子色（固定，变体不动这层）--- */
:root {
  --nord0:  #2e3440; --nord1:  #3b4252; --nord2:  #434c5e; --nord3:  #4c566a;
  --nord4:  #d8dee9; --nord5:  #e5e9f0; --nord6:  #eceff4;
  --nord7:  #8fbcbb; --nord8:  #88c0d0; --nord9:  #81a1c1; --nord10: #5e81ac;
  --nord11: #bf616a; --nord12: #d08770; --nord13: #ebcb8b; --nord14: #a3be8c; --nord15: #b48ead;

  /* ---语义令牌（变体只改这层）--- */
  --bg-0:        var(--nord0);   /* 画布 */
  --bg-1:        var(--nord1);   /* 面板/抽屉（浮起） */
  --bg-2:        var(--nord2);   /* 组件底/亮阶/选中条 */
  --bg-3:        var(--nord3);   /* 导向标记/滚动条/强发丝线 */
  --bg-sunken:   #282e39;       /* 下沉层 darken(nord0) */
  --line-0:      var(--nord1);  /* 画布级发丝线 */
  --line-1:      var(--nord2);  /* 面板内发丝线 */
  --line-2:      var(--nord3);  /* 组件边/强发丝线 */
  --selection-bg: var(--nord2);
  --selection-fg: var(--nord6);
  --text:        var(--nord4);
  --text-hi:     var(--nord6);
  --text-hover:  var(--nord5);
  --text-dim:    color-mix(in srgb, var(--nord4) 65%, transparent);
  --text-faint:  var(--nord3);
  --comment:     #616e88;        /* 代码注释：官方 nord3 在 nord0 上太淡，Nord 社区提亮值 */
  --accent:      var(--nord8);   /* ★ 主强调，变体唯一替换点 */
  --accent-2:    var(--nord9);
  --accent-3:    var(--nord10);
  --on-accent:   var(--nord0);
  --danger:      var(--nord11);
  --warn:        var(--nord13);
  --success:     var(--nord14);
  --info:        var(--nord9);
  --frost-ring: 0 0 0 1px var(--accent), 0 0 0 4px color-mix(in srgb, var(--accent) 18%, transparent); /* frost 焦点环 */
  --shadow-float: 0 4px 14px rgba(24, 27, 35, 0.4);
  --shadow-raised: 0 1px 3px rgba(24, 27, 35, 0.3);
  --ease-out:    cubic-bezier(0.215, 0.61, 0.355, 1);
  --font-sans: 'Rubik', 'HarmonyOS Sans SC', 'HarmonyOS_Sans_SC', system-ui, -apple-system, 'Segoe UI', Roboto, 'PingFang SC', 'Microsoft YaHei', sans-serif;
  --font-mono: 'Source Code Pro', 'Cascadia Code', ui-monospace, Menlo, Consolas, monospace;
  --radius: 3px;
}

/* ---全局字体（排除图标，避免盖 FA 字形）--- */
body {
  background-color: var(--bg-0) !important;
  color: var(--text) !important;
  font-family: var(--font-sans) !important;
}
input, textarea, select, option,
button:not(.fa-solid):not(.fa-regular):not([class*="fa-"]),
.select2-container, .select2-container .select2-selection,
.text_pole, .widthNatural, #send_textarea, #dialogue_del_mes {
  font-family: var(--font-sans) !important;
}
.mes_text, .mes_text p, .mes_text span,
.ch_name, .mesIDDisplay, .mes_timer, .tokenCounterDisplay {
  font-family: var(--font-sans) !important;
  color: var(--text) !important;
}
.ch_name { color: var(--text-hi) !important; font-weight: 600 !important; letter-spacing: 0.01em !important; }
code, pre, .hljs, .katex { font-family: var(--font-mono) !important; }

/* ---面板/抽屉：nord1 浮起 + nord2 发丝线 + 微浮影（给结构与层次）--- */
.drawer-content,
#left-nav-panel, #right-nav-panel,
#character_popup, #dialogue_popup, .popup,
#top-settings-holder, #send_form,
#WorldInfo, #floatingPrompt, .draggable {
  background-color: var(--bg-1) !important;
  border: 1px solid var(--line-1) !important;
  border-radius: var(--radius) !important;
  box-shadow: var(--shadow-raised) !important;
  backdrop-filter: none !important;
  color: var(--text) !important;
}

/* WorldInfo 补 0.7px 发丝缝：与用户设置面板(rectTop 34.0)精确齐平；
   侧栏 fillLeft/fillRight 保持 ST 原生 top:0 贴顶，不动 */
#WorldInfo {
  top: calc(var(--topBarBlockSize) + 0.7px) !important;
}

/* ---标题：nord2 亮条 + 底部 frost 发丝线--- */
.inline-drawer-header,
.standoutHeader,
.drawer-content h3, .drawer-content h4:not(.margin0),
#character_popup h3, .popup h3 {
  background: var(--bg-2) !important;
  color: var(--text-hi) !important;
  border: none !important;
  text-shadow: none !important;
  font-weight: 600 !important;
  letter-spacing: 0.02em !important;
  padding: 6px 12px !important;
  min-height: 36px !important;
  box-sizing: border-box !important;
  border-radius: var(--radius) !important;
}
.inline-drawer-header,
.standoutHeader,
.drawer-content h3, .drawer-content h4:not(.margin0),
#character_popup h3, .popup h3 {
  border-bottom: 1px solid var(--accent) !important;
}
.inline-drawer-header .inline-drawer-icon { color: var(--text-dim) !important; transition: color .12s var(--ease-out) !important; }
.inline-drawer-header:hover .inline-drawer-icon { color: var(--text-hi) !important; }

/* ---按钮：nord2 底 + nord3 细边（可点击感）；hover 升一阶底色；active 转 frost；选中=主强调实底--- */
.menu_button, .right_menu_button,
input[type="button"], input[type="submit"] {
  background-color: var(--bg-2) !important;
  color: var(--text) !important;
  border: 1px solid var(--line-2) !important;
  border-radius: var(--radius) !important;
  text-shadow: none !important;
  filter: none !important;
  box-shadow: none !important;
  transition: background-color .14s var(--ease-out), color .14s var(--ease-out), border-color .14s var(--ease-out) !important;
}
.menu_button:hover, .right_menu_button:hover,
input[type="button"]:hover, input[type="submit"]:hover {
  background-color: var(--bg-3) !important;
  color: var(--text-hi) !important;
  border-color: var(--accent) !important;
}
.menu_button:active, .right_menu_button:active,
input[type="button"]:active, input[type="submit"]:active {
  background-color: var(--accent-3) !important;
  color: var(--nord6) !important;
  border-color: var(--accent-3) !important;
}
.menu_button.active, .menu_button.selected {
  background-color: var(--accent) !important;
  color: var(--on-accent) !important;
  border-color: var(--accent) !important;
}

/* ---ST 原生状态色恢复：扁平化别压掉语义态---
   收藏=aurora 黄(ST fav_on 的 golden)、世界书/角色书已链接=冰青(world_set/toggleEnabled)、删除=aurora 红底(red_button) */
.fav_on { color: var(--nord13) !important; }
.world_set, .toggleEnabled, .bulk_edit_overlay_active { color: var(--accent) !important; }
.menu_button.red_button, .red_button {
  background-color: var(--danger) !important;
  color: var(--nord6) !important;
  border-color: var(--danger) !important;
}
.menu_button.red_button:hover, .red_button:hover {
  background-color: var(--danger) !important;
  color: var(--nord6) !important;
  border-color: var(--danger) !important;
}

/* ---主操作（发送/继续）：唯一实底冰青；hover 转 nord7（frost 双色阶呼应）--- */
#send_but, #mes_continue {
  background-color: var(--accent) !important;
  color: var(--on-accent) !important;
  border: 1px solid var(--accent) !important;
  border-radius: var(--radius) !important;
  text-shadow: none !important;
  filter: none !important;
  box-shadow: none !important;
  transition: background-color .14s var(--ease-out), border-color .14s var(--ease-out) !important;
}
#send_but:hover, #mes_continue:hover {
  background-color: var(--nord7) !important;
  border-color: var(--nord7) !important;
  color: var(--on-accent) !important;
}
#send_but:active, #mes_continue:active {
  background-color: var(--nord9) !important;
  border-color: var(--nord9) !important;
  color: var(--on-accent) !important;
}

/* ---输入区：nord2 底 + nord3 细边；focus frost 焦点环--- */
.text_pole, textarea,
input[type="text"], input[type="password"], input[type="number"],
#send_textarea, select {
  background-color: var(--bg-2) !important;
  color: var(--text) !important;
  border: 1px solid var(--line-2) !important;
  border-radius: var(--radius) !important;
  box-shadow: none !important;
  transition: border-color .14s var(--ease-out), box-shadow .14s var(--ease-out) !important;
}
.text_pole:focus, textarea:focus,
input[type="text"]:focus, input[type="password"]:focus,
input[type="number"]:focus, #send_textarea:focus, select:focus {
  border-color: var(--accent) !important;
  box-shadow: var(--frost-ring) !important;
  outline: none !important;
}
.text_pole::placeholder, textarea::placeholder, #send_textarea::placeholder {
  color: var(--text-dim) !important;
  opacity: 1 !important;
}
select option { background-color: var(--bg-1) !important; color: var(--text) !important; }
select option:checked { background-color: var(--selection-bg) !important; color: var(--selection-fg) !important; }

/* ---select2 选择框：与输入控件同语言（世界书选择/模型选择等），去掉 ST 原生渐变分层--- */
.select2-container .select2-selection--single,
.select2-container .select2-selection--multiple,
.select2-container--default .select2-selection--single,
.select2-container--default .select2-selection--multiple {
  background-color: var(--bg-2) !important;
  background-image: none !important;
  border: 1px solid var(--bg-3) !important;
  border-radius: var(--radius) !important;
  box-shadow: none !important;
  color: var(--text) !important;
  min-height: 36px !important;
  box-sizing: border-box !important;
}
.select2-container--default .select2-selection--single .select2-selection__rendered {
  line-height: 34px !important;
}
/* 单选框箭头/X 按 34px 内框居中（库默认 26px 是按 28px 框设计的） */
.select2-container--default .select2-selection--single .select2-selection__arrow {
  height: 34px !important;
}
.select2-container--default .select2-selection--single .select2-selection__clear {
  height: 34px !important;
  line-height: 34px !important;
}
.select2-container--default.select2-container--focus .select2-selection--single,
.select2-container--default.select2-container--focus .select2-selection--multiple,
.select2-container--default.select2-container--open .select2-selection--single,
.select2-container--default.select2-container--open .select2-selection--multiple {
  background-color: var(--bg-2) !important;
  background-image: none !important;
  border: 1px solid var(--accent) !important;
  border-radius: var(--radius) !important;
  box-shadow: none !important;
}
.select2-container .select2-selection * { outline: none !important; }
.select2-container .select2-selection__rendered { color: var(--text) !important; }
.select2-container .select2-selection__placeholder { color: var(--text-dim) !important; }
/* 多选框内嵌搜索 textarea：它会被全局 textarea 规则画出第二个框，必须扒光 */
.select2-container .select2-search__field {
  color: var(--text) !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}
.select2-dropdown {
  background-color: var(--bg-1) !important;
  border: 1px solid var(--bg-3) !important;
  border-radius: var(--radius) !important;
  color: var(--text) !important;
}
.select2-container--default .select2-results__option--highlighted[aria-selected] {
  background-color: var(--selection-bg) !important;
  color: var(--selection-fg) !important;
}

/* ===== 桌面端原生下拉弹层接管（base-select，Chrome/Edge 135+）=====
   仅鼠标设备+支持的浏览器生效；手机/平板保持原生底部面板；
   Firefox/Safari/旧版整段无效，回落原生弹层（上面 option 规则兜底）。
   ST 已用 background-image 自画箭头，隐藏 Chrome 的 picker-icon 防双箭头。 */
@media (hover: hover) and (pointer: fine) {
  select, ::picker(select) {
    appearance: base-select;
  }
  ::picker(select) {
    background-color: var(--bg-1);
    border: 1px solid var(--bg-3);
    border-radius: var(--radius);
    padding: 4px;
    box-shadow: var(--shadow-float);
  }
  /* option 样式直接写 option：::picker(select) option 伪元素禁带后代选择器，整条会被丢弃 */
  select option {
    border-radius: 2px;
    padding: 4px 8px;
    background-color: transparent !important;
    color: var(--text) !important;
  }
  select::picker-icon {
    display: none;
  }
  /* 弹开态高亮：base-select 首次点击焦点进弹层，按钮本体不触发 :focus，
     用 :open 补开态焦点环（不支持的浏览器整行丢弃，无副作用） */
  select:open {
    border-color: var(--accent) !important;
  }
  /* 当前值透明底 + ✓ 冰青；高亮只给悬停/键盘焦点（focus-visible 防鼠标点开时的幻影高亮） */
  select option:checked {
    background-color: transparent !important;
    color: var(--text) !important;
  }
  select option::checkmark {
    color: var(--accent);
  }
  select option:disabled {
    opacity: 0.6;
  }
  select option:hover,
  select option:focus-visible {
    background-color: color-mix(in srgb, var(--accent) 14%, transparent) !important;
    color: var(--text-hi) !important;
  }
}

/* ---聊天区：下沉一阶；消息间发丝线分隔；当前消息 nord2 提亮--- */
#chat {
  background-color: var(--bg-sunken) !important;
  border: 1px solid var(--line-1) !important;
  border-radius: var(--radius) !important;
  box-shadow: none !important;
}
.mes { border-bottom: 1px solid var(--line-0) !important; }
.last_mes {
  background-color: var(--bg-2) !important;
  border-radius: var(--radius) !important;
}
.mes_text { color: var(--text) !important; }
.mes_block, .mes_text p, .mes_text li { color: var(--text) !important; }
.last_mes .mes_text { color: var(--text) !important; }

/* ---正文格式：frost 阶梯给层级，正文不单调---
   加粗=亮白 / 斜体=雾蓝 / 加粗斜体=冰绿 / 删除=灰字红线 / 引用=冰绿+淡青底 */
.mes_text strong, .mes_text b {
  color: var(--text-hi) !important;
  font-weight: 700 !important;
}
.mes_text em, .mes_text i {
  color: var(--accent-2) !important;
}
.mes_text strong em, .mes_text em strong,
.mes_text strong i, .mes_text b i,
.mes_text b em, .mes_text em b {
  color: var(--nord7) !important;
}
/* 删除线：文字压灰，线留一丝 aurora 红（语义：移除） */
.mes_text del, .mes_text s {
  color: var(--comment) !important;
  text-decoration-color: color-mix(in srgb, var(--danger) 55%, transparent) !important;
}
/* 引用块：淡青 tonal 底 + 冰绿文字（quote 色不再被正文规则压住） */
.mes_text blockquote {
  background: color-mix(in srgb, var(--accent) 6%, transparent) !important;
  border: none !important;
  border-left: 2px solid color-mix(in srgb, var(--accent) 40%, transparent) !important;
  border-radius: 0 var(--radius) var(--radius) 0 !important;
  padding: 8px 12px !important;
  margin: 8px 0 !important;
}
.mes_text blockquote, .mes_text blockquote p, .mes_text blockquote span {
  color: var(--nord7) !important;
}
/* 标题分级：h1/h2 带发丝底线，h3 纯字，h4+ 降一档 */
.mes_text h1, .mes_text h2 {
  color: var(--text-hi) !important;
  font-weight: 700 !important;
  border-bottom: 1px solid var(--line-0) !important;
  padding-bottom: 4px !important;
  margin: 0.9em 0 0.45em !important;
}
.mes_text h1 { font-size: 1.45em !important; }
.mes_text h2 { font-size: 1.25em !important; font-weight: 600 !important; }
.mes_text h3 {
  color: var(--text-hi) !important;
  font-size: 1.12em !important;
  font-weight: 600 !important;
  margin: 0.9em 0 0.4em !important;
}
.mes_text h4, .mes_text h5, .mes_text h6 {
  color: var(--text-hover) !important;
  font-weight: 600 !important;
  margin: 0.8em 0 0.35em !important;
}

/* ---代码块：IDE 风——编辑器卡片 + 语言标签栏 + 官方语法色--- */
/* 编辑器卡片：nord0 底（比聊天沉层亮一阶），等宽，横向滚动不换行 */
code.hljs {
  display: block !important;
  position: relative !important;
  background-color: var(--bg-0) !important;
  color: var(--text) !important;
  border: 1px solid var(--line-1) !important;
  border-radius: var(--radius) !important;
  box-shadow: none !important;
  padding: 12px 40px 12px 14px !important;
  margin: 8px 0 !important;
  font-family: var(--font-mono) !important;
  font-size: 0.86em !important;
  line-height: 1.6 !important;
  tab-size: 4 !important;
  white-space: pre !important;
  overflow-x: auto !important;
}
/* hljs 语法 span 会被 .mes_text span 全局规则抢成 sans，必须点名夺回等宽 */
code.hljs, code.hljs span { font-family: var(--font-mono) !important; }
/* pre 只是外壳时拆壳，卡片统一由 code.hljs 承担 */
pre:has(> code.hljs) {
  background: transparent !important;
  border: none !important;
  padding: 0 !important;
  margin: 0 !important;
}
/* 语言标签栏（IDE 编辑器标题栏；ST 用 custom-language-* 标语言） */
code.hljs[class*="custom-language-"] { padding-top: 32px !important; }
code.hljs[class*="custom-language-"]::before {
  content: 'code';
  position: absolute !important;
  top: 0 !important; left: 0 !important; right: 0 !important;
  padding: 5px 14px 6px !important;
  font-family: var(--font-sans) !important;
  font-size: 11px !important;
  letter-spacing: 0.12em !important;
  text-transform: uppercase !important;
  color: var(--text-dim) !important;
  border-bottom: 1px solid var(--line-0) !important;
  white-space: normal !important;
}
code.hljs.custom-language-python::before { content: 'python'; }
code.hljs.custom-language-javascript::before { content: 'javascript'; }
code.hljs.custom-language-typescript::before { content: 'typescript'; }
code.hljs.custom-language-json::before { content: 'json'; }
code.hljs.custom-language-bash::before { content: 'bash'; }
code.hljs.custom-language-shell::before { content: 'shell'; }
code.hljs.custom-language-html::before { content: 'html'; }
code.hljs.custom-language-xml::before { content: 'xml'; }
code.hljs.custom-language-css::before { content: 'css'; }
code.hljs.custom-language-scss::before { content: 'scss'; }
code.hljs.custom-language-c::before { content: 'c'; }
code.hljs.custom-language-cpp::before { content: 'c++'; }
code.hljs.custom-language-csharp::before { content: 'c#'; }
code.hljs.custom-language-java::before { content: 'java'; }
code.hljs.custom-language-rust::before { content: 'rust'; }
code.hljs.custom-language-go::before { content: 'go'; }
code.hljs.custom-language-sql::before { content: 'sql'; }
code.hljs.custom-language-yaml::before { content: 'yaml'; }
code.hljs.custom-language-markdown::before { content: 'markdown'; }
code.hljs.custom-language-lua::before { content: 'lua'; }
code.hljs.custom-language-php::before { content: 'php'; }
code.hljs.custom-language-ruby::before { content: 'ruby'; }
code.hljs.custom-language-perl::before { content: 'perl'; }
code.hljs.custom-language-r::before { content: 'r'; }
code.hljs.custom-language-kotlin::before { content: 'kotlin'; }
code.hljs.custom-language-swift::before { content: 'swift'; }
code.hljs.custom-language-dockerfile::before { content: 'dockerfile'; }
code.hljs.custom-language-ini::before { content: 'ini'; }
code.hljs.custom-language-diff::before { content: 'diff'; }
code.hljs.custom-language-stscript::before { content: 'stscript'; }
/* 复制按钮：faint 常态，hover 冰青 */
code.hljs .code-copy {
  color: var(--text-dim) !important;
  opacity: 1 !important;
  transition: color .12s var(--ease-out) !important;
}
code.hljs .code-copy:hover { color: var(--accent) !important; }
/* 行内代码：小芯片 */
code:not(.hljs) {
  background-color: var(--bg-1) !important;
  color: var(--text) !important;
  border: 1px solid var(--line-1) !important;
  border-radius: 3px !important;
  padding: 0.1em 0.35em !important;
  font-family: var(--font-mono) !important;
  font-size: 0.86em !important;
}
/* hljs 官方语法色（code.hljs 作用域加权，压过 ST bright.min.css） */
code.hljs .hljs-keyword, code.hljs .hljs-selector-tag, code.hljs .hljs-operator,
code.hljs .hljs-punctuation, code.hljs .hljs-tag, code.hljs .hljs-name,
code.hljs .hljs-built_in { color: var(--nord9) !important; }
code.hljs .hljs-function .hljs-title, code.hljs .hljs-title.function_,
code.hljs .hljs-section { color: var(--nord8) !important; }
code.hljs .hljs-title.class_, code.hljs .hljs-type { color: var(--nord7) !important; }
code.hljs .hljs-string, code.hljs .hljs-template-string,
code.hljs .hljs-addition { color: var(--nord14) !important; }
code.hljs .hljs-number, code.hljs .hljs-literal { color: var(--nord15) !important; }
code.hljs .hljs-attr, code.hljs .hljs-attribute, code.hljs .hljs-variable,
code.hljs .hljs-constant, code.hljs .hljs-params { color: var(--nord4) !important; }
code.hljs .hljs-comment, code.hljs .hljs-quote { color: var(--comment) !important; font-style: italic !important; }
code.hljs .hljs-regexp { color: var(--nord13) !important; }
code.hljs .hljs-meta { color: var(--nord10) !important; }
code.hljs .hljs-symbol, code.hljs .hljs-bullet { color: var(--nord12) !important; }
code.hljs .hljs-deletion { color: var(--nord11) !important; }
code.hljs .hljs-emphasis { font-style: italic !important; }
code.hljs .hljs-strong { font-weight: 700 !important; }

/* ---滚动条：幽灵化——6px 半透明雪色，平时几乎隐形，hover 才显形--- */
::-webkit-scrollbar { width: 6px !important; height: 6px !important; }
/* 轨道垫一层半透明 nord0：全透明会把背景纹理透出来，与面板形成割裂列 */
::-webkit-scrollbar-track { background: color-mix(in srgb, var(--bg-0) 35%, transparent) !important; }
::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, var(--text) 16%, transparent) !important;
  border-radius: 3px !important;
}
::-webkit-scrollbar-thumb:hover { background: color-mix(in srgb, var(--accent) 55%, transparent) !important; }
::-webkit-scrollbar-corner { background: transparent !important; }
* { scrollbar-color: color-mix(in srgb, var(--text) 16%, transparent) color-mix(in srgb, var(--bg-0) 35%, transparent) !important; scrollbar-width: thin !important; }

/* ---选区：官方 = nord2 底 + nord6 字--- */
::selection { background: var(--selection-bg) !important; color: var(--selection-fg) !important; }
/* 表单控件底色本身就是 nord2，选区换冰青实底才分辨得出 */
textarea::selection, input::selection {
  background: var(--accent) !important;
  color: var(--on-accent) !important;
}

/* ---标签 tag：次级强调 nord9 淡底 + nord9 细边--- */
.tag {
  background-color: color-mix(in srgb, var(--accent-2) 14%, transparent) !important;
  color: var(--accent-2) !important;
  border: 1px solid color-mix(in srgb, var(--accent-2) 40%, transparent) !important;
  border-radius: var(--radius) !important;
  box-shadow: none !important;
}
.tag::before { color: var(--accent-2) !important; }

/* ---滑条/勾选/单选--- */
input[type="range"] {
  background: var(--bg-2) !important;
  border: 1px solid var(--line-2) !important;
  border-radius: var(--radius) !important;
  filter: none !important;
  box-shadow: none !important;
}
input[type="range"]::-webkit-slider-thumb {
  background: var(--accent) !important;
  border: 1px solid var(--accent-3) !important;
  border-radius: 50% !important;
  box-shadow: none !important;
}
input[type="range"]::-moz-range-thumb {
  background: var(--accent) !important;
  border: 1px solid var(--accent-3) !important;
  border-radius: 50% !important;
}
input[type="checkbox"], input[type="radio"] { accent-color: var(--accent) !important; }

/* ---浮层微阴影--- */
#character_popup, #dialogue_popup, .popup, .draggable,
.toast, .toast-container .toast,
.tooltip, .tooltip-inner {
  box-shadow: var(--shadow-float) !important;
}

/* ---弹窗/toastr：nord2 浮层 + 发丝线，语义色染标题--- */
.toast, .toast-container .toast {
  background-color: var(--bg-2) !important;
  color: var(--text) !important;
  border: 1px solid var(--line-2) !important;
  border-radius: var(--radius) !important;
  text-shadow: none !important;
}
.toast-success .toast-title { color: var(--success) !important; }
.toast-error .toast-title { color: var(--danger) !important; }
.toast-warning .toast-title { color: var(--warn) !important; }
.toast-info .toast-title { color: var(--info) !important; }

/* ---头像：纯圆角，不描边；img 撑满容器+object-fit:cover 强制裁切---
   ST 原生 cover 挂 body.big-avatars，body 无该 class 时竖版原图 letterbox（img 缩成竖条留白）。
   主题侧兜底，不依赖 body class（与 Gruvbox 同思路） */
.avatar, .avatar img { border: none !important; border-radius: var(--radius) !important; }
.avatar img { width: var(--avatar-base-width) !important; height: var(--avatar-base-height) !important; object-fit: cover !important; object-position: center !important; }
/* hotswap 顶栏/inline 头像：原生 .avatar img 固定 base 尺寸（约30px），容器被 avatars_inline 拉成50→大框包小图。
   点名撑满容器，specificity 压过原生与 avatars_inline_small 因子规则 */
.avatar.inline_avatar img, #HotSwapWrapper .avatar img, .hotswap .avatar img { width: var(--avatar-base-width) !important; height: var(--avatar-base-height) !important; object-fit: cover !important; object-position: center !important; }

/* ---顶栏图标：只改颜色与 hover（不沿用 Gruvbox 的 openIcon 满高/topBarIconSize 配方）--- */
#top-settings-holder .drawer-icon {
  color: var(--text-dim) !important;
  text-shadow: none !important;
  filter: none !important;
  transition: color .14s var(--ease-out) !important;
}
#top-settings-holder .drawer-icon:hover { color: var(--text-hi) !important; }
#top-settings-holder .drawer-icon.openIcon { color: var(--accent) !important; }
/* Remix/Eva mask 图标 hover 修正：顶栏 hover=白、展开=冰青。
   ::before 背景色仅适用于挂 mask 的图标（FA 原生字形的 color 与 background-color
   同色会融成色块——映射表里没有的 FA 类不要加进这组规则） */
#top-settings-holder .drawer-icon:hover::before,
#top-settings-holder .drawer-toggle:hover .drawer-icon::before {
  background-color: var(--text-hi) !important;
}
/* 点开立刻变蓝（不等鼠标移开）：优先级必须压过上面的 hover 白 */
#top-settings-holder .drawer-icon.openIcon::before,
#top-settings-holder .drawer-toggle:hover .drawer-icon.openIcon::before {
  background-color: var(--accent) !important;
}
/* 顶栏展开线：点击后从中心向段两缘生长，相邻展开的段无缝连成一条。
   定位上下文挂 drawer-toggle（drawer-content 是它的兄弟不是子代，不吃 absolute 重锚），
   严禁给 .drawer 加 position:relative——会把 drawer-content 锚到图标段上 */
#top-settings-holder .drawer-toggle {
  position: relative !important;
  width: 100% !important;
  align-self: stretch !important;
  display: flex !important;
  justify-content: center !important;
  align-items: center !important;
}
#top-settings-holder .drawer-toggle::after {
  content: '' !important;
  position: absolute !important;
  top: 0 !important;
  left: 50% !important;
  width: 0 !important;
  height: 2px !important;
  background: var(--accent) !important;
  transform: translateX(-50%) !important;
  transition: width .22s var(--ease-out) !important;
}
#top-settings-holder .drawer:has(.drawer-icon.openIcon) .drawer-toggle::after { width: 100% !important; }

/* ---链接：主强调，hover 加下划线--- */
a, a:visited { color: var(--accent) !important; text-decoration: none !important; }
a:hover { text-decoration: underline !important; }

/* ---工具提示 tooltip--- */
.tooltip, [data-toggle="tooltip"] + .tooltip, .tooltip-inner, .tooltip-arrow {
  background-color: var(--bg-2) !important;
  color: var(--text) !important;
  border: 1px solid var(--line-2) !important;
  border-radius: var(--radius) !important;
  text-shadow: none !important;
  box-shadow: none !important;
}

/* ---列表条目：面板内发丝线分隔，hover 升一阶--- */
.character_div, .character_select,
#WorldInfo .world_entry,
.prompt_manager_prompt_entry,
.world_info_entry {
  border-bottom: 1px solid var(--line-1) !important;
  background-color: transparent !important;
}
.character_div:hover, .character_select:hover,
#WorldInfo .world_entry:hover, .world_info_entry:hover {
  background-color: var(--bg-2) !important;
}

/* ---分割线--- */
hr, .drawer-content hr { border: none !important; border-top: 1px solid var(--line-1) !important; }
.mes hr, .mes_text hr { border: none !important; border-top: 1px solid var(--line-0) !important; }

/* ---设置面板宽松化：留白加大，菜单不局促--- */
.drawer-content {
  padding: 12px 14px !important;
  line-height: 1.7 !important;
}
/* 三栏之间拉开 */
#user-settings-block-content { gap: 18px !important; }
/* 分区标题上下透气 */
.standoutHeader, #user-settings-block h4 {
  margin-top: 16px !important;
  margin-bottom: 8px !important;
}
/* 行内的标题条豁免段顶距：与同行控件起点对齐（宽松化只管堆叠场景） */
.range-block .standoutHeader { margin-top: 0 !important; }
/* 折叠分区盒内留白；上直下圆，与标题亮条拼成一件组件 */
.standoutHeader~.inline-drawer-content {
  padding: 10px 12px !important;
  border-radius: 0 0 var(--radius) var(--radius) !important;
}

/* ---圆角统一：收编 ST 原生 10px 圆角，全主题一档 3px--- */
.popup .popper-modal, .list-group, .tokenGraph, #cfgConfig,
.character_select, .suggested_reply, .avatar-container,
#select_chat_popup, body .ui-widget-content,
.settingsSectionWrap, .zoomed_avatar img,
#show_more_messages, .info-block,
.welcomePanel, .welcomeRecent .recentChatList .recentChat {
  border-radius: var(--radius) !important;
}

/* ---全局克制：去文字阴影/入场动画--- */
* { text-shadow: none !important; }
.mes, .drawer-content { animation: none !important; }

/* ============================================================
 * modern-ui 插件适配（body.th-modern-enabled 限定，纯 ST 零命中）
 * ============================================================ */
body.th-modern-enabled .th-modern-wi-entry,
body.th-modern-enabled .th-modern-wi-list,
body.th-modern-enabled [class^="th-modern-wi"] {
  background-color: var(--bg-1) !important;
  border: 1px solid var(--line-1) !important;
  border-radius: var(--radius) !important;
  color: var(--text) !important;
}
body.th-modern-enabled .th-modern-panel-header,
body.th-modern-enabled .th-modern-section-title,
body.th-modern-enabled .th-modern-wi-header {
  background: var(--bg-2) !important;
  color: var(--text-hi) !important;
  border: none !important;
  border-bottom: 1px solid var(--accent) !important;
  border-radius: var(--radius) var(--radius) 0 0 !important;
}
body.th-modern-enabled input.th-modern-wi-shortcut-control[type="text"],
body.th-modern-enabled input.th-modern-wi-shortcut-control[type="number"],
body.th-modern-enabled select.th-modern-wi-shortcut-control {
  background-color: var(--bg-2) !important;
  color: var(--text) !important;
  border: 1px solid var(--line-2) !important;
  border-radius: var(--radius) !important;
}
body.th-modern-enabled .th-modern-card,
body.th-modern-enabled .th-modern-item {
  background-color: var(--bg-1) !important;
  border: 1px solid var(--line-1) !important;
  border-radius: var(--radius) !important;
}
body.th-modern-enabled .th-modern-card:hover,
body.th-modern-enabled .th-modern-item:hover {
  background-color: var(--bg-2) !important;
  border-color: var(--accent) !important;
}

/* ---modern-ui select 弹层主题化（PC 专用，塞桌面媒体）--- */
@media (hover: hover) and (pointer: fine) {
  body.th-modern-enabled .select2-container--default .select2-results__option--highlighted[aria-selected] {
    background-color: var(--selection-bg) !important;
    color: var(--selection-fg) !important;
  }
  body.th-modern-enabled .select2-container--default .select2-selection--single {
    background-color: var(--bg-2) !important;
    color: var(--text) !important;
    border: 1px solid var(--line-2) !important;
    border-radius: var(--radius) !important;
  }
}
